args.sparql:
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film { dbr:Ethnic_Notions dbr:Gordon_of_Ghost_City }
  OPTIONAL { ?film dbo:director ?director. }
  OPTIONAL { ?film dbp:director ?director. }
  OPTIONAL { ?director dbo:deathDate ?d1. }
  OPTIONAL { ?director dbp:deathDate ?d2. }
  BIND(COALESCE(?d1, ?d2) AS ?deathDate)
  OPTIONAL { ?film rdfs:label ?filmLabel. FILTER(langMatches(lang(?filmLabel), "EN")) }
  OPTIONAL { ?director rdfs:label ?directorLabel. FILTER(langMatches(lang(?directorLabel), "EN")) }
}
ORDER BY ?deathDate
LIMIT 1

