PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate WHERE {
  VALUES ?film {
    dbr:Ethnic_Notions dbr:Gordon_of_Ghost_City
  }
  OPTIONAL {
    ?film(dbo:director | dbp:director) ?director .
    OPTIONAL {
      ?director(dbo:deathDate | dbp:deathDate) ?deathDate .
    }
  }
  OPTIONAL {
    ?film rdfs:label ?filmLabel .
    FILTER(langMatches(lang(?filmLabel) , "EN"))
  }
  OPTIONAL {
    ?director rdfs:label ?directorLabel .
    FILTER(langMatches(lang(?directorLabel) , "EN"))
  }
}
ORDER BY ?deathDate
LIMIT 1

